"use client";

import React, { useRef } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { jsPDF } from "jspdf";
import { StockPriceChart } from "./charts/StockPriceChart";
import { RankingBarChart } from "./charts/RankingBarChart";
import { ShareholdingPieChart } from "./charts/ShareholdingPieChart";
import Image from "next/image";
import IrisLogo from "./IrisLogo";

// Function to generate the PDF
const generatePdf = async (element: HTMLElement, fileName: string) => {
  const doc = new jsPDF();

  // Convert the element into a canvas to be rendered into the PDF
  const canvas = await html2canvas(element);
  const imgData = canvas.toDataURL("image/png");

  // Add the image to the PDF (starting at (0,0) with full page size)
  doc.addImage(
    imgData,
    "PNG",
    0,
    0,
    doc.internal.pageSize.width,
    doc.internal.pageSize.height
  );
  doc.save(fileName); // Save the generated PDF with the provided file name
};

// Helper function for rendering UI components (charts)
const renderPdfUiComponent = (component: any, index: number) => {
  switch (component.type) {
    case "stock_price_chart":
      return (
        <StockPriceChart
          key={index}
          data={component.data}
          title={component.title}
          animationDuration={0}
        />
      );
    case "ranking_bar_chart":
      return (
        <RankingBarChart
          key={index}
          data={component.data}
          title={component.title}
          labelKey={component.labelKey}
          valueKey={component.valueKey}
          animationDuration={0}
        />
      );
    case "pie_chart":
      return (
        <ShareholdingPieChart
          key={index}
          data={component.data}
          title={component.title}
          animationDuration={0}
        />
      );
    default:
      return null;
  }
};

// Main component for the PDF layout
export const PdfDocumentLayout = ({ message }: { message: any }) => {
  const pdfRef = useRef<HTMLDivElement>(null);

  if (!message) {
    return null;
  }

  const currentDate = new Date().toLocaleDateString(); // Current date for the PDF

  return (
    <div
      ref={pdfRef}
      style={{ fontFamily: "Arial, sans-serif", padding: "20px" }}
    >
      {/* Cover Page */}
      <div
        style={{ textAlign: "center", padding: "50px", position: "relative" }}
      >
        <div
          style={{
            position: "absolute",
            top: "0",
            left: "0",
            width: "100%",
            height: "100%",
            background: "linear-gradient(45deg, #00FFFF, #004A63)",
            zIndex: -1,
          }}
        ></div>
        <Image
          src="/brainfoglogo-dark.png"
          alt="Brainfog Logo"
          width={200}
          height={200}
          style={{
            objectFit: "contain",
            margin: "0 auto",
            borderRadius: "10px",
          }}
        />
        <h1
          style={{
            fontSize: "40px",
            fontWeight: "bold",
            color: "#FFFFFF",
            marginTop: "20px",
          }}
        >
          IRIS Report
        </h1>
        <p style={{ color: "#FFFFFF", fontSize: "18px", marginTop: "20px" }}>
          Professional AI-Powered Insights
        </p>
        <p style={{ color: "#FFFFFF", fontSize: "14px", marginTop: "10px" }}>
          Date: {currentDate}
        </p>
      </div>

      {/* Content (IRIS Response) */}
      <div style={{ marginTop: "40px", padding: "20px" }}>
        <h2>IRIS Insights</h2>
        <ReactMarkdown
          children={message.content} // Assuming the content is markdown formatted
          remarkPlugins={[remarkGfm]}
        />

        {/* Render UI components like charts */}
        {message.components?.map((component: any, index: number) =>
          renderPdfUiComponent(component, index)
        )}
      </div>

      {/* Footer */}
      <div
        style={{
          position: "absolute",
          bottom: "20px",
          width: "100%",
          textAlign: "center",
          fontSize: "12px",
          color: "#AAAAAA",
        }}
      >
        <p>&copy; 2025 Brainfog. All rights reserved.</p>
      </div>

      {/* Button to trigger PDF download */}
      <button onClick={() => generatePdf(pdfRef.current!, "IRIS_Report.pdf")}>
        Download PDF
      </button>
    </div>
  );
};
